import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';
import toast from 'react-hot-toast';
import { FiUser, FiPhone, FiLock, FiSave, FiEdit2, FiX, FiPackage, FiCalendar, FiAward } from 'react-icons/fi';

const Profile = () => {
    const { user, logout } = useAuth();
    const [loading, setLoading] = useState(false);
    const [editMode, setEditMode] = useState(false);
    const [userStats, setUserStats] = useState({ totalProducts: 0, createdAt: '' });
    const [formData, setFormData] = useState({
        name: '',
        phone: '',
        currentPassword: '',
        newPassword: '',
        confirmPassword: ''
    });
    const [error, setError] = useState('');

    useEffect(() => {
        if (user) {
            setFormData({
                name: user.name,
                phone: user.phone,
                currentPassword: '',
                newPassword: '',
                confirmPassword: ''
            });
            fetchUserStats();
        }
    }, [user]);

    const fetchUserStats = async () => {
        try {
            if (user?.type === 'vendedor') {
                const response = await api.get(`/products/seller/${user.id}`);
                if (response.data.success) {
                    setUserStats({
                        totalProducts: response.data.products.length,
                        createdAt: user.createdAt
                    });
                }
            } else {
                setUserStats({
                    totalProducts: 0,
                    createdAt: user.createdAt
                });
            }
        } catch (error) {
            console.error('Erro ao buscar estatísticas:', error);
        }
    };

    const validateAngolaPhone = (phone) => {
        const cleanPhone = phone.replace(/\D/g, '');
        if (cleanPhone.length === 9 && cleanPhone.startsWith('9')) return true;
        if (cleanPhone.length === 12 && cleanPhone.startsWith('2449')) return true;
        return false;
    };

    const handleChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
        setError('');
    };

    const handlePhoneChange = (e) => {
        let value = e.target.value.replace(/\D/g, '');
        if (value.length > 9) value = value.slice(0, 9);
        setFormData({ ...formData, phone: value });
    };

    const handleSave = async () => {
        setError('');
        
        if (formData.name.length < 3) {
            setError('Nome deve ter pelo menos 3 caracteres');
            return;
        }
        
        if (formData.phone !== user?.phone && !validateAngolaPhone(formData.phone)) {
            setError('Número de telefone inválido');
            return;
        }
        
        if (formData.newPassword) {
            if (formData.newPassword.length < 6) {
                setError('A nova senha deve ter pelo menos 6 caracteres');
                return;
            }
            if (formData.newPassword !== formData.confirmPassword) {
                setError('As novas senhas não coincidem');
                return;
            }
            if (!formData.currentPassword) {
                setError('Digite sua senha atual');
                return;
            }
        }
        
        setLoading(true);
        
        try {
            const updateData = {
                name: formData.name,
                phone: formData.phone
            };
            
            if (formData.newPassword) {
                updateData.currentPassword = formData.currentPassword;
                updateData.newPassword = formData.newPassword;
            }
            
            const response = await api.put('/auth/profile', updateData);
            
            if (response.data.success) {
                toast.success('Perfil atualizado!');
                user.name = formData.name;
                user.phone = formData.phone;
                localStorage.setItem('techmarket_user', JSON.stringify(user));
                setEditMode(false);
                setFormData({
                    name: formData.name,
                    phone: formData.phone,
                    currentPassword: '',
                    newPassword: '',
                    confirmPassword: ''
                });
            }
        } catch (error) {
            toast.error(error.response?.data?.error || 'Erro ao atualizar');
        } finally {
            setLoading(false);
        }
    };

    const handleCancel = () => {
        setFormData({
            name: user?.name || '',
            phone: user?.phone || '',
            currentPassword: '',
            newPassword: '',
            confirmPassword: ''
        });
        setEditMode(false);
        setError('');
    };

    const formatDate = (dateString) => {
        if (!dateString) return 'Data não disponível';
        const date = new Date(dateString);
        return date.toLocaleDateString('pt-BR', {
            day: '2-digit',
            month: 'long',
            year: 'numeric'
        });
    };

    if (!user) return null;

    return (
        <div className="max-w-2xl mx-auto">
            <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
                {/* Cabeçalho com gradiente suave */}
                <div className="bg-gradient-to-r from-blue-50 to-indigo-50 px-6 py-5 border-b border-gray-100">
                    <div className="flex items-center justify-between">
                        <div>
                            <h1 className="text-xl font-semibold text-gray-800">Meu Perfil</h1>
                            <p className="text-sm text-gray-500 mt-1">Gerencie suas informações</p>
                        </div>
                        {!editMode && (
                            <button
                                onClick={() => setEditMode(true)}
                                className="text-blue-600 hover:text-blue-700 transition text-sm flex items-center gap-1.5 bg-white px-3 py-1.5 rounded-lg shadow-sm"
                            >
                                <FiEdit2 size={14} />
                                <span>Editar</span>
                            </button>
                        )}
                    </div>
                </div>
                
                <div className="p-6">
                    {error && (
                        <div className="bg-red-50 text-red-600 text-sm p-3 rounded-lg mb-5 border border-red-100">
                            {error}
                        </div>
                    )}
                    
                    <div className="space-y-5">
                        {/* Nome */}
                        <div>
                            <label className="block text-sm font-medium text-gray-600 mb-1">
                                <FiUser className="inline mr-2" size={14} /> Nome De Usuário
                            </label>
                            {editMode ? (
                                <input
                                    type="text"
                                    name="name"
                                    value={formData.name}
                                    onChange={handleChange}
                                    className="w-full px-4 py-2 border border-gray-200 rounded-lg focus:outline-none focus:border-blue-400 focus:ring-1 focus:ring-blue-100 transition"
                                />
                            ) : (
                                <div className="px-4 py-2 bg-gray-50 rounded-lg text-gray-700 border border-gray-100">
                                    {user.name}
                                </div>
                            )}
                        </div>
                        
                        {/* Telefone */}
                        <div>
                            <label className="block text-sm font-medium text-gray-600 mb-1">
                                <FiPhone className="inline mr-2" size={14} /> Telefone
                            </label>
                            {editMode ? (
                                <div>
                                    <input
                                        type="tel"
                                        name="phone"
                                        value={formData.phone}
                                        onChange={handlePhoneChange}
                                        className="w-full px-4 py-2 border border-gray-200 rounded-lg focus:outline-none focus:border-blue-400 focus:ring-1 focus:ring-blue-100 transition"
                                        placeholder="923456789"
                                    />
                                    <p className="text-xs text-gray-400 mt-1">Apenas números. Ex: 923456789</p>
                                </div>
                            ) : (
                                <div className="px-4 py-2 bg-gray-50 rounded-lg text-gray-700 border border-gray-100">
                                    {user.phone}
                                </div>
                            )}
                        </div>
                        
                        {/* Tipo de conta com badge */}
                        <div>
                            <label className="block text-sm font-medium text-gray-600 mb-1">Tipo de conta</label>
                            <div className="px-4 py-2 bg-gray-50 rounded-lg border border-gray-100">
                                {user.type === 'vendedor' ? (
                                    <span className="inline-flex items-center gap-2">
                                        <span className="w-2 h-2 bg-blue-500 rounded-full"></span>
                                        <span className="text-gray-700">Vendedor</span>
                                        <span className="text-xs text-gray-400 ml-2">-</span>
                                    </span>
                                ) : (
                                    <span className="inline-flex items-center gap-2">
                                        <span className="w-2 h-2 bg-green-500 rounded-full"></span>
                                        <span className="text-gray-700">Comprador</span>
                                        <span className="text-xs text-gray-400 ml-2">-</span>
                                    </span>
                                )}
                            </div>
                        </div>
                        
                        {/* Informações específicas */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pt-2">
                            {user.type === 'vendedor' && (
                                <div className="bg-gradient-to-br from-blue-50 to-blue-100/50 rounded-xl p-4 border border-blue-100">
                                    <div className="flex items-center gap-2 text-blue-600 mb-2">
                                        <FiPackage size={16} />
                                        <span className="text-xs font-medium uppercase tracking-wide">Anúncios</span>
                                    </div>
                                    <div className="text-2xl font-semibold text-blue-700">
                                        {userStats.totalProducts}
                                    </div>
                                    <div className="text-xs text-blue-500 mt-1">
                                        {userStats.totalProducts === 1 ? 'produto anunciado' : 'produtos anunciados'}
                                    </div>
                                </div>
                            )}
                            
                            <div className={`${user.type === 'vendedor' ? '' : 'col-span-2'} bg-gray-50 rounded-xl p-4 border border-gray-100`}>
                                <div className="flex items-center gap-2 text-gray-500 mb-2">
                                    <FiCalendar size={16} />
                                    <span className="text-xs font-medium uppercase tracking-wide">Conta Criada em:</span>
                                </div>
                                <div className="text-gray-700 font-medium">
                                    {formatDate(userStats.createdAt || user.createdAt)}
                                </div>
                            </div>
                        </div>
                        
                        {/* Alterar senha - modo edição */}
                        {editMode && (
                            <div className="border-t border-gray-100 pt-4 mt-2">
                                <h3 className="text-sm font-medium text-gray-700 mb-3 flex items-center gap-2">
                                    <FiLock size={14} />
                                    Alterar senha
                                </h3>
                                <div className="space-y-3">
                                    <div>
                                        <label className="block text-xs text-gray-500 mb-1">Senha atual</label>
                                        <input
                                            type="password"
                                            name="currentPassword"
                                            value={formData.currentPassword}
                                            onChange={handleChange}
                                            placeholder="Digite sua senha atual"
                                            className="w-full px-4 py-2 border border-gray-200 rounded-lg focus:outline-none focus:border-blue-400 text-sm"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-xs text-gray-500 mb-1">Nova senha</label>
                                        <input
                                            type="password"
                                            name="newPassword"
                                            value={formData.newPassword}
                                            onChange={handleChange}
                                            placeholder="Mínimo 6 caracteres"
                                            className="w-full px-4 py-2 border border-gray-200 rounded-lg focus:outline-none focus:border-blue-400 text-sm"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-xs text-gray-500 mb-1">Confirmar nova senha</label>
                                        <input
                                            type="password"
                                            name="confirmPassword"
                                            value={formData.confirmPassword}
                                            onChange={handleChange}
                                            placeholder="Digite novamente"
                                            className="w-full px-4 py-2 border border-gray-200 rounded-lg focus:outline-none focus:border-blue-400 text-sm"
                                        />
                                    </div>
                                </div>
                            </div>
                        )}
                        
                        {/* Botões */}
                        {editMode && (
                            <div className="flex gap-3 pt-4">
                                <button
                                    onClick={handleSave}
                                    disabled={loading}
                                    className="flex-1 bg-blue-600 text-white py-2.5 rounded-lg text-sm font-medium hover:bg-blue-700 transition flex items-center justify-center gap-2 shadow-sm"
                                >
                                    <FiSave size={14} />
                                    {loading ? 'Salvando...' : 'Salvar alterações'}
                                </button>
                                <button
                                    onClick={handleCancel}
                                    className="flex-1 bg-gray-100 text-gray-600 py-2.5 rounded-lg text-sm font-medium hover:bg-gray-200 transition flex items-center justify-center gap-2"
                                >
                                    <FiX size={14} />
                                    Cancelar
                                </button>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default Profile;
